// ChatGPT mobile wallpaper for Quantumult X. Experimental; verify on device.
// Embedded original photo. No external requests, cookies, or conversation logging.
// Disable the rewrite and reload to remove. Dark overlay: .48 in CSS.
(function () {
  try {
    if (!/^https:\/\/chatgpt\.com\//i.test($request.url)) return $done({});
    var body = $response.body;
    var headers = $response.headers || {};
    var ct = Object.keys(headers).filter(function(k){return k.toLowerCase()==='content-type';})[0];
    if (typeof body !== 'string' || !ct || !/text\/html/i.test(headers[ct]) || !/<\/head\s*>/i.test(body)) return $done({});
    if (body.indexOf('id="qx-personal-wallpaper"') !== -1) return $done({});
    var css = "\n@media (max-width: 1024px) {\nhtml { background:#171717 !important; }\nbody { isolation:isolate; background:transparent !important; }\nbody::before { content:\"\"; position:fixed; inset:0; z-index:-1; pointer-events:none;\nbackground-image:linear-gradient(rgba(0,0,0,.48),rgba(0,0,0,.48)),url(\"data:image/jpeg;base64,\");\nbackground-size:cover; background-position:65% center; background-repeat:no-repeat; }\nbody, .dark, .light { --main-surface-primary:transparent !important; --main-surface-secondary:rgba(25,25,25,.78) !important; --bg-primary:transparent !important; }\n#root, #__next, main, [role=\"main\"], #thread, #thread > div, [data-testid=\"conversation-turns\"], [data-testid^=\"conversation-turn-\"] { background-color:transparent !important; }\nmain .bg-token-main-surface-primary, main .bg-token-bg-primary { background-color:transparent !important; }\n[data-message-author-role=\"assistant\"] { color:#f5f5f5 !important; text-shadow:0 1px 3px rgba(0,0,0,.9); }\n#prompt-textarea { color:#f5f5f5 !important; }\nform:has(#prompt-textarea) { background:rgba(28,28,28,.86) !important; border-radius:24px; }\n}\n";
    // Reuse an existing style nonce when supplied; do not remove CSP headers.
    var match = body.match(/<style\b[^>]*\bnonce=["']([^"']+)["']/i) || body.match(/<script\b[^>]*\bnonce=["']([^"']+)["']/i);
    var nonce = match ? ' nonce="' + match[1].replace(/[&<>"']/g,'') + '"' : '';
    var style = '<style id="qx-personal-wallpaper"' + nonce + '>' + css + '</style>';
    console.log('[ChatGPT wallpaper] HTML style injected');
    $done({body:body.replace(/<\/head\s*>/i,style+'</head>')});
  } catch (e) {
    console.log('[ChatGPT wallpaper] skipped');
    $done({});
  }
})();
